// A separate worker orchestration layer: compares an existing run to a refined run.
export function compareRuns(coarse,fine){const a=coarse.frames.at(-1),b=fine.frames.at(-1);if(Math.abs(a.t-b.t)>1e-10)throw Error('Runs ended at different times; refinement comparison is invalid.');let error=0,norm=0,max=0;for(let j=0;j<coarse.config.N;j++){const d=a.w[j]-b.w[2*j];error+=d*d;norm+=b.w[2*j]**2;max=Math.max(max,Math.abs(d));}return {coarseN:coarse.config.N,fineN:fine.config.N,coarseDt:coarse.dt,fineDt:fine.dt,T:a.t,relativeL2:Math.sqrt(error/Math.max(norm,1e-30)),maxAbs:max,scope:'One joint grid/time refinement comparison at final time; not an error bound or an observed convergence order.'};}
